            await At("R3-S08.shift_duty");await Click("由本人接收本时段同一账板 · 瑟拉 / Sela");await At("R3-S08.shift_duty");var unfinished=Nodes(_panels.Peek()).OfType<OptionButton>().Single();Check("handover_unknown_default",unfinished.Selected==0);unfinished.Select(1);await Click("实际标未完项并核同板交接");await At("R3-S08.auxiliary_receipt");await Click("由本人接收本时段同一账板 · 托宾 / Tobin");await At("R3-S08.auxiliary_receipt");await Click("接收本班实际两段交接并释放岗位");var final=await _store.SnapshotAsync();Check("finite_same_board_two_real_receptions",final.Items.Count(i=>i.Id==Mist.Application.R3ShiftWork.R3ShiftWorkService.BoardId)==1&&final.Receipts.Count(r=>r.ActionType=="shift_named_person_same_board_received")==2);Check("once_zero_reward",final.Receipts.Count(r=>r.SemanticKey=="R3:shift-work:resolution")==1&&before.Balances.OrderBy(x=>x.Key).SequenceEqual(final.Balances.OrderBy(x=>x.Key)));Check("two_posts_released",final.Entities.Count(e=>e.Id.StartsWith("workpost:ROLE-R3-SHIFT-",StringComparison.Ordinal)&&e.Kind=="released_post")==2);
            CloseAllPanels();await OpenSystem();await Click("继续当前冒险");await At("R3-S08.demand_board");Check("actual_completion_and_draft_recovered",(await R3Shift().ViewAsync()).State!.Completed&&(await _store.GetDraftAsync(R3Shift().Package.DraftTask))?.Body?.StartsWith("Sela covers",StringComparison.Ordinal)==true);await Click("查看已取得本班档案");await Click("本班公共值班板");await Click("编辑对应交接便条");Check("archive_dispatch_same_writer",_routing.Top==R3ShiftWriterTitle&&_r3ShiftWriter?.Text.StartsWith("Sela covers",StringComparison.Ordinal)==true);await Click("返回");
